<?php require_once 'partials.php';require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){ $cid=role()==='cliente'?$_SESSION['user']['client_id']:(int)($_POST['client_id']??1);$_SESSION['tickets'][]=['id'=>next_id('tickets'),'client_id'=>$cid,'subject'=>$_POST['subject'],'category'=>$_POST['category'],'status'=>'Recebido','date'=>date('d/m/Y'),'text'=>$_POST['text'],'reply'=>''];header('Location:chamados.php');exit;}
header_page('Chamados','tickets');$tickets=$_SESSION['tickets'];if(role()==='cliente')$tickets=array_values(array_filter($tickets,fn($x)=>$x['client_id']==$_SESSION['user']['client_id']));?>
<header class="pagehead"><div><span class="kicker">ATENDIMENTO</span><h1>Chamados</h1><p>Centralize dúvidas e solicitações em um histórico único.</p></div><button onclick="ticketModal.showModal()">+ Novo chamado</button></header>
<div class="stack"><?php foreach(array_reverse($tickets) as $t):?><section class="card"><div class="sectionhead"><div><span class="kicker">#TSP-<?=e($t['id'])?> · <?=e($t['date'])?></span><h2><?=e($t['subject'])?></h2></div><i class="status"><?=e($t['status'])?></i></div><p><?=e($t['text'])?></p><?php if($t['reply']):?><div class="summary"><b>Equipe TSP</b><p><?=e($t['reply'])?></p></div><?php endif;?></section><?php endforeach;?></div>
<dialog id="ticketModal"><form method="post" class="modal"><div class="sectionhead"><h2>Novo chamado</h2><button type="button" class="x" onclick="ticketModal.close()">×</button></div><?php if(role()!=='cliente'):?><label>Cliente<select name="client_id"><?php foreach($_SESSION['clients'] as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><?php endif;?><label>Assunto<input name="subject" required></label><label>Categoria<select name="category"><option>Processo</option><option>Financeiro</option><option>Documentos</option><option>Geral</option></select></label><label>Mensagem<textarea name="text" required></textarea></label><button>Abrir chamado</button></form></dialog><?php footer_page();?>